/* ===== 30_home.js ===== */
/* Home page: the search and the chips open the answer card under the search. Without JavaScript the chips are plain links. */
(() => {
'use strict';
if (document.body.dataset.page !== 'home') return;
const {ROOT, loadCoins, initSearch, answerHTML} = window.SigTide;
const hero = document.getElementById('hero');
const form = hero.querySelector('form[data-search]');
const slot = document.getElementById('answer');
const card = slot.querySelector('.h-card');
const more = slot.querySelector('.h-more');
const chips = [...hero.querySelectorAll('.h-chip')];

function show(c) {
  card.innerHTML = answerHTML(c);
  more.href = `${ROOT}coins/${c.s.toLowerCase()}/index.html`;
  more.querySelector('span').textContent = `See the full ${c.s} page`;
  hero.classList.add('has-answer');
  chips.forEach(a => a.classList.toggle('is-on', a.dataset.sym === c.s));
  // The sign-up forms offer the coin they just looked at, unless the reader already picked one there.
  document.querySelectorAll('form.join-form select[name="coin"]').forEach(s => {
    if (!s.dataset.picked && [...s.options].some(o => o.value === c.s)) s.value = c.s;
  });
  if (matchMedia('(max-width:959px)').matches) {
    requestAnimationFrame(() => {
      const top = slot.getBoundingClientRect().top + scrollY - document.querySelector('.top').offsetHeight - 10;
      window.scrollTo({top, behavior: matchMedia('(prefers-reduced-motion:reduce)').matches ? 'auto' : 'smooth'});
    });
  }
}

initSearch(form, c => { form.querySelector('input').value = c.n; show(c); });
chips.forEach(a => a.addEventListener('click', e => {
  e.preventDefault();
  loadCoins().then(list => {
    const c = list.coins.find(x => x.s === a.dataset.sym);
    if (c) show(c); else location.href = a.href;
  }).catch(() => { location.href = a.href; });
}));
})();

